14	  MAGNETIC_CORNER_ENTRIES,
15	  MAGNETIC_CORNER_SIZE_THRESHOLD,
16	  MAGNETIC_CORNER_STROKE_WIDTH,
17	  MAGNETIC_CORNER_TEXT_SELECTOR,
18	  SHARE_BUTTON,
19	} from "../config/component.config.js";
20	import type {
21	  ClipboardPort,
22	  MagneticCornerBox,
23	  MagneticCornerGsap,
24	  MagneticCornerTrackerOptions,
25	  ShareButtonInitOptions,
26	  ToastNotifier,
27	  UrlProvider,
28	} from "../types/component.types.js";
29	import { Toast } from "./Toast.js";
30	import { FrameScheduler } from "../utils/FrameScheduler.js";
