138	
139	
140	function getGsapGlobal(): MagneticCornerGsap | undefined {
141	  return (window as { gsap?: MagneticCornerGsap }).gsap;
142	}
143	
144	
145	export class MagneticCornerTracker {
146	  private static _globalInstances: MagneticCornerTracker[] = [];
147	
148	  private readonly gsap: MagneticCornerGsap;
149	  private readonly cfg: Required<Omit<MagneticCornerTrackerOptions, "root">>;
150	  private readonly H = { x0: 0, y0: 0, x1: 100, y1: 50, L: 20, p: 0 };
151	  private readonly cache: Record<string, string | number> = {} as Record<
152	    string,
153	    string | number
154	  >;
155	  private hoverEl: HTMLElement | null = null;
156	  private hoverTween: { kill?: () => void } | null = null;
157	  private progressTween: { kill?: () => void } | null = null;
158	  private dirty = false;
159	  private rafId = 0;
160	  private pendingMove: {
161	    el: HTMLElement;
162	    txt: HTMLElement | null;
163	    x: number;
164	    y: number;
165	  } | null = null;
166	  private moveScheduled = false;
167	  private readonly rectCache = new Map<HTMLElement, MagneticCornerBox>();
168	  private readonly arms: Record<string, SVGPathElement>;
169	  private readonly svg: SVGSVGElement;
170	  private readonly onScrollOrResize: () => void;
171	  private _mounted = false;
172	
173	  constructor(
174	    opts: MagneticCornerTrackerOptions,
175	    gsapInstance: MagneticCornerGsap,
176	  ) {
177	    this.gsap = gsapInstance;
178	    const d = MAGNETIC_CORNER_DEFAULTS;
179	    this.cfg = {
180	      gap: opts.gap ?? d.gap,
181	      pull: opts.pull ?? d.pull,
182	      pullText: opts.pullText ?? d.pullText,
183	      cornerFollow: opts.cornerFollow ?? opts.pull ?? d.pull,
184	      color: opts.color ?? d.color,
185	    };
186	    this.svg = this.buildSvg();
187	    this.arms = this.buildArms();
188	    this.onScrollOrResize = (): void => {
189	      this.rectCache.clear();
190	    };
191	  }
192	
193	  mount(scope: HTMLElement | null, linkSelector: string): void {
194	    if (this._mounted) return;
195	    this._mounted = true;
196	    window.addEventListener("scroll", this.onScrollOrResize, { passive: true });
197	    window.addEventListener("resize", this.onScrollOrResize);
198	    const parent = scope ?? document.body;
199	    parent.appendChild(this.svg);
200	    this.rafLoop();
201	    const elements = scope
202	      ? scope.querySelectorAll<HTMLElement>(linkSelector)
203	      : document.querySelectorAll<HTMLElement>(linkSelector);
204	    this.bind(elements);
205	  }
206	
207	  
208	  static createForDrawer(
209	    drawer: HTMLElement,
210	    gsapInstance: MagneticCornerGsap,
211	  ): MagneticCornerTracker | null {
212	    if (!MAGNETIC_CORNER_ENABLED) return null;
213	    const tracker = new MagneticCornerTracker({}, gsapInstance);
214	    tracker.mount(drawer, MAGNETIC_CORNER_DRAWER_LINK_SELECTOR);
215	    return tracker;
216	  }
217	
218	  
219	  static init(options: MagneticCornerTrackerOptions = {}): MagneticCornerTracker | null {
220	    const gsap = getGsapGlobal();
221	    if (!MAGNETIC_CORNER_ENABLED) return null;
222	    if (!gsap || MAGNETIC_CORNER_ENTRIES.length === 0) return null;
223	    const root = options.root ?? document;
224	
225	    
226	    
227	    MagneticCornerTracker.destroyAll();
228	
229	    let first: MagneticCornerTracker | null = null;
230	    for (const entry of MAGNETIC_CORNER_ENTRIES) {
231	      const list = root.querySelectorAll<HTMLElement>(entry.selector);
232	      if (list.length === 0) continue;
233	      const tracker = new MagneticCornerTracker(
234	        {
235	          ...(entry.options as MagneticCornerTrackerOptions),
236	          root,
237	        },
238	        gsap,
239	      );
240	      tracker.mount(root instanceof HTMLElement ? root : null, entry.selector);
241	      MagneticCornerTracker._globalInstances.push(tracker);
242	      if (!first) first = tracker;
243	    }
244	    return first;
245	  }
246	
247	  
248	  static destroyAll(): void {
249	    for (const t of MagneticCornerTracker._globalInstances) {
250	      t.destroy();
251	    }
252	    MagneticCornerTracker._globalInstances.length = 0;
253	  }
254	
255	  private gsapTo(target: unknown, vars: object): { kill?: () => void } {
256	    return this.gsap.to(target, vars) as { kill?: () => void };
257	  }
258	
259	  private buildSvg(): SVGSVGElement {
260	    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
261	    Object.assign(svg.style, {
262	      position: "fixed",
263	      inset: "0",
264	      width: "100%",
265	      height: "100%",
266	      pointerEvents: "none",
267	      zIndex: "101",
268	      overflow: "visible",
269	    });
270	    return svg;
271	  }
272	
273	  private buildArms(): Record<string, SVGPathElement> {
274	    const out: Record<string, SVGPathElement> = {};
275	    const ns = "http://www.w3.org/2000/svg";
276	    MAGNETIC_CORNER_ARM_IDS.forEach((id) => {
277	      const p = document.createElementNS(ns, "path");
278	      p.setAttribute("fill", "none");
279	      p.setAttribute("stroke", this.cfg.color);
280	      p.setAttribute("stroke-linecap", "square");
281	      p.setAttribute("stroke-width", MAGNETIC_CORNER_STROKE_WIDTH);
282	      p.style.filter = `drop-shadow(0 0 5px ${this.cfg.color}88)`;
283	      this.svg.appendChild(p);
284	      out[id] = p;
285	    });
286	    return out;
287	  }
288	
289	  private rafLoop = (): void => {
290	    if (this.dirty) {
291	      this.flush();
292	      this.dirty = false;
293	    }
294	    this.rafId = FrameScheduler.request(this.rafLoop);
295	  };
296	
297	  private flush(): void {
298	    const { x0, y0, x1, y1, L, p } = this.H;
299	    const visible = p > 0.001;
300	
301	    MAGNETIC_CORNER_ARM_IDS.forEach((id, i) => {
302	      const el = this.arms[id];
303	      if (!visible) {
304	        el.setAttribute("visibility", "hidden");
305	        this.cache[id + "d"] = "";
306	        this.cache[id + "da"] = "";
307	        this.cache[id + "do"] = "";
308	        return;
309	      }
310	
311	      el.removeAttribute("visibility");
312	      const off = +(L * (1 - p)).toFixed(3);
313	      const len = +L.toFixed(3);
314	      const defs: [number, number, number, number][] = [
315	        [x0, y0, x0 + L, y0],
316	        [x0, y0, x0, y0 + L],
317	        [x1, y0, x1 - L, y0],
318	        [x1, y0, x1, y0 + L],
319	        [x0, y1, x0 + L, y1],
320	        [x0, y1, x0, y1 - L],
321	        [x1, y1, x1 - L, y1],
322	        [x1, y1, x1, y1 - L],
323	      ];
324	      const [ax, ay, bx, by] = defs[i] as [number, number, number, number];
325	      const d = `M ${+ax.toFixed(2)},${+ay.toFixed(2)} L ${+bx.toFixed(2)},${+by.toFixed(2)}`;
326	      const lenStr = String(len);
327	      const offStr = String(off);
328	      if (this.cache[id + "d"] !== d) {
329	        el.setAttribute("d", d);
330	        this.cache[id + "d"] = d;
331	      }
332	      if (this.cache[id + "da"] !== lenStr) {
333	        el.setAttribute("stroke-dasharray", lenStr);
334	        this.cache[id + "da"] = lenStr;
335	      }
336	      if (this.cache[id + "do"] !== offStr) {
337	        el.setAttribute("stroke-dashoffset", offStr);
338	        this.cache[id + "do"] = offStr;
339	      }
340	    });
341	  }
342	
343	  private measureBox(el: HTMLElement): MagneticCornerBox {
344	    const cached = this.rectCache.get(el);
345	    if (cached) return cached;
346	    const g = this.cfg.gap;
347	    const r = el.getBoundingClientRect();
348	    const s = Math.min(r.width, r.height);
349	    const box: MagneticCornerBox = {
350	      cx: r.left + r.width / 2,
351	      cy: r.top + r.height / 2,
352	      hw: r.width / 2,
353	      hh: r.height / 2,
354	      x0: r.left - g,
355	      y0: r.top - g,
356	      x1: r.right + g,
357	      y1: r.bottom + g,
358	      L:
359	        s >= MAGNETIC_CORNER_SIZE_THRESHOLD
360	          ? MAGNETIC_CORNER_ARM_FIXED
361	          : Math.max(MAGNETIC_CORNER_ARM_MIN, s * MAGNETIC_CORNER_ARM_RATIO_SMALL),
362	      sw: Math.max(1.5, s * 0.022),
363	    };
364	    this.rectCache.set(el, box);
365	    return box;
366	  }
367	
368	  private hoverIn(box: MagneticCornerBox): void {
369	    this.hoverTween?.kill?.();
370	    this.progressTween?.kill?.();
371	    Object.values(this.arms).forEach((a) =>
372	      a.setAttribute("stroke-width", MAGNETIC_CORNER_STROKE_WIDTH),
373	    );
374	    this.hoverTween = this.gsapTo(this.H, {
375	      x0: box.x0,
376	      y0: box.y0,
377	      x1: box.x1,
378	      y1: box.y1,
379	      L: box.L,
380	      duration: 0.42,
381	      ease: "power3.out",
382	      onUpdate: () => (this.dirty = true),
383	      overwrite: "auto",
384	    });
385	    this.progressTween = this.gsapTo(this.H, {
386	      p: 1,
387	      duration: 0.32,
388	      ease: "power3.out",
389	      onUpdate: () => (this.dirty = true),
390	    });
391	  }
392	
393	  private hoverOut(): void {
394	    this.hoverTween?.kill?.();
395	    this.hoverTween = null;
396	    this.progressTween?.kill?.();
397	    this.progressTween = this.gsapTo(this.H, {
398	      p: 0,
399	      duration: 0.25,
400	      ease: "power2.in",
401	      onUpdate: () => (this.dirty = true),
402	      onComplete: () => {
403	        this.hoverTween?.kill?.();
404	        this.hoverTween = null;
405	        this.dirty = true;
406	      },
407	    });
408	  }
409	
410	  private isActiveEl(el: HTMLElement): boolean {
411	    return MAGNETIC_CORNER_ACTIVE_EXCLUDE.some((s) => el.closest(s) !== null);
412	  }
413	
414	  private bind(elements: NodeListOf<Element>): void {
415	    const { pull, pullText, cornerFollow } = this.cfg;
416	    const g = this.gsap;
417	
418	    elements.forEach((el) => {
419	      const target = el as HTMLElement;
420	      const txt = target.querySelector<HTMLElement>(MAGNETIC_CORNER_TEXT_SELECTOR) ?? null;
421	
422	      target.addEventListener("mouseenter", () => {
423	        if (this.isActiveEl(target)) return;
424	        this.hoverEl = target;
425	        const box = this.measureBox(target);
426	        this.hoverIn(box);
427	      });
428	
429	      target.addEventListener("mouseleave", () => {
430	        this.hoverEl = null;
431	        FrameScheduler.request(() => {
432	          if (!this.hoverEl) this.hoverOut();
433	        });
434	        g.to(target, { x: 0, y: 0, duration: 0.5, ease: "elastic.out(1,.5)" });
435	        if (txt)
436	          g.to(txt, { x: 0, y: 0, duration: 0.4, ease: "elastic.out(1,.5)" });
437	      });
438	
439	      target.addEventListener("mousemove", (e: MouseEvent) => {
440	        this.pendingMove = { el: target, txt, x: e.clientX, y: e.clientY };
441	        if (this.moveScheduled) return;
442	        this.moveScheduled = true;
443	        FrameScheduler.request(() => {
444	          this.moveScheduled = false;
445	          const p = this.pendingMove;
446	          if (!p || this.hoverEl !== p.el) return;
447	          if (this.isActiveEl(p.el)) {
448	            this.hoverEl = null;
449	            this.hoverOut();
450	            return;
451	          }
452	          const b = this.rectCache.get(p.el);
453	          if (!b) return;
454	          const rx = (p.x - b.cx) / b.hw;
455	          const ry = (p.y - b.cy) / b.hh;
456	          const bx = rx * b.hw * pull;
457	          const by = ry * b.hh * pull;
458	          
459	          const cornerOffset = pull !== 0 ? cornerFollow : 0;
460	          const bxCorner = rx * b.hw * cornerOffset;
461	          const byCorner = ry * b.hh * cornerOffset;
462	          g.to(p.el, {
463	            x: bx,
464	            y: by,
465	            duration: 0.35,
466	            ease: "power2.out",
467	            overwrite: "auto",
468	          });
469	          if (p.txt && pull !== 0)
470	            g.to(p.txt, {
471	              x: bx * (pullText / pull),
472	              y: by * (pullText / pull),
473	              duration: 0.25,
474	              ease: "power2.out",
475	              overwrite: "auto",
476	            });
477	          this.hoverTween?.kill?.();
478	          this.hoverTween = this.gsapTo(this.H, {
479	            x0: b.x0 + bxCorner,
480	            y0: b.y0 + byCorner,
481	            x1: b.x1 + bxCorner,
482	            y1: b.y1 + byCorner,
483	            duration: 0.35,
484	            ease: "power2.out",
485	            onUpdate: () => (this.dirty = true),
486	            overwrite: "auto",
487	          });
488	        });
489	      });
490	    });
491	  }
492	
493	  destroy(): void {
494	    window.removeEventListener("scroll", this.onScrollOrResize);
495	    window.removeEventListener("resize", this.onScrollOrResize);
496	    this._mounted = false;
497	    this.rectCache.clear();
498	    FrameScheduler.cancel(this.rafId);
499	    this.gsap.killTweensOf([this.H]);
500	    this.hoverTween?.kill?.();
501	    this.progressTween?.kill?.();
502	    
503	    this.H.p = 0;
504	    this.dirty = true;
505	    this.flush();
506	    this.svg.remove();
507	  }
508	}
