import {
  CORNER_BRACKET_SIZE_FIXED,
  CORNER_BRACKET_SIZE_MIN,
  CORNER_SIZE_THRESHOLD,
  MAGNETIC_CORNER_ACTIVE_EXCLUDE,
  MAGNETIC_CORNER_ARM_FIXED,
  MAGNETIC_CORNER_ARM_IDS,
  MAGNETIC_CORNER_ARM_MIN,
  MAGNETIC_CORNER_ARM_RATIO_SMALL,
  MAGNETIC_CORNER_ENABLED,
  MAGNETIC_CORNER_DEFAULTS,
  MAGNETIC_CORNER_DRAWER_LINK_SELECTOR,
  MAGNETIC_CORNER_ENTRIES,
  MAGNETIC_CORNER_SIZE_THRESHOLD,
  MAGNETIC_CORNER_STROKE_WIDTH,
  MAGNETIC_CORNER_TEXT_SELECTOR,
  SHARE_BUTTON,
} from "../config/component.config.js";
import type {
  ClipboardPort,
  MagneticCornerBox,
  MagneticCornerGsap,
  MagneticCornerTrackerOptions,
  ShareButtonInitOptions,
  ToastNotifier,
  UrlProvider,
} from "../types/component.types.js";
import { Toast } from "./Toast.js";
import { FrameScheduler } from "../utils/FrameScheduler.js";



class BrowserClipboardPort implements ClipboardPort {
  async writeText(text: string): Promise<void> {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return;
    }
    BrowserClipboardPort.legacyCopy(text);
  }

  private static legacyCopy(text: string): void {
    const textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.setAttribute("readonly", "true");
    textarea.style.position = "fixed";
    textarea.style.top = "-9999px";
    document.body.appendChild(textarea);
    textarea.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(textarea);
    if (!ok) throw new Error("copy failed");
  }
}

class WindowUrlProvider implements UrlProvider {
  getCurrentUrl(): string {
    return window.location.href;
  }
}


export class ShareButton {
  private readonly button: HTMLButtonElement;
  private readonly clipboard: ClipboardPort;
  private readonly urlProvider: UrlProvider;
  private readonly notifier: ToastNotifier;
  private readonly successText: string;
  private readonly failText: string;

  constructor(
    button: HTMLButtonElement,
    deps: {
      clipboard: ClipboardPort;
      urlProvider: UrlProvider;
      notifier: ToastNotifier;
      successText?: string;
      failText?: string;
    },
  ) {
    this.button = button;
    this.clipboard = deps.clipboard;
    this.urlProvider = deps.urlProvider;
    this.notifier = deps.notifier;
    this.successText = deps.successText ?? SHARE_BUTTON.successText;
    this.failText = deps.failText ?? SHARE_BUTTON.failText;
  }

  mount(): void {
    if (this.button.dataset[SHARE_BUTTON.boundAttr] === "true") return;
    this.button.dataset[SHARE_BUTTON.boundAttr] = "true";
    this.button.addEventListener("click", () => void this.handleClick());
  }

  private async handleClick(): Promise<void> {
    const override = this.button.dataset.copyUrl;
    const url =
      override && override.trim() !== ""
        ? override
        : this.urlProvider.getCurrentUrl();
    try {
      await this.clipboard.writeText(url);
      this.notifier.setVisibleOn(this.successText, "success");
    } catch (error) {
      this.notifier.setVisibleOn(this.failText, "error");
    }
  }


  static init(options: ShareButtonInitOptions | string = {}): void {
    const selector =
      typeof options === "string"
        ? options
        : (options.selector ?? SHARE_BUTTON.selector);
    const root =
      typeof options === "string" ? document : (options.root ?? document);
    const buttons = root.querySelectorAll<HTMLButtonElement>(selector);
    if (buttons.length === 0) return;

    const clipboard = new BrowserClipboardPort();
    const urlProvider = new WindowUrlProvider();
    const notifier = new Toast();

    buttons.forEach((button) => {
      const share = new ShareButton(button, {
        clipboard,
        urlProvider,
        notifier,
        successText: button.dataset.copySuccessText ?? SHARE_BUTTON.successText,
        failText: button.dataset.copyFailText ?? SHARE_BUTTON.failText,
      });
      share.mount();
    });
  }
}



function getGsapGlobal(): MagneticCornerGsap | undefined {
  return (window as { gsap?: MagneticCornerGsap }).gsap;
}


export class MagneticCornerTracker {
  private static _globalInstances: MagneticCornerTracker[] = [];

  private readonly gsap: MagneticCornerGsap;
  private readonly cfg: Required<Omit<MagneticCornerTrackerOptions, "root">>;
  private readonly H = { x0: 0, y0: 0, x1: 100, y1: 50, L: 20, p: 0 };
  private readonly cache: Record<string, string | number> = {} as Record<
    string,
    string | number
  >;
  private hoverEl: HTMLElement | null = null;
  private hoverTween: { kill?: () => void } | null = null;
  private progressTween: { kill?: () => void } | null = null;
  private dirty = false;
  private rafId = 0;
  private pendingMove: {
    el: HTMLElement;
    txt: HTMLElement | null;
    x: number;
    y: number;
  } | null = null;
  private moveScheduled = false;
  private readonly rectCache = new Map<HTMLElement, MagneticCornerBox>();
  private readonly arms: Record<string, SVGPathElement>;
  private readonly svg: SVGSVGElement;
  private readonly onScrollOrResize: () => void;
  private _mounted = false;

  constructor(
    opts: MagneticCornerTrackerOptions,
    gsapInstance: MagneticCornerGsap,
  ) {
    this.gsap = gsapInstance;
    const d = MAGNETIC_CORNER_DEFAULTS;
    this.cfg = {
      gap: opts.gap ?? d.gap,
      pull: opts.pull ?? d.pull,
      pullText: opts.pullText ?? d.pullText,
      cornerFollow: opts.cornerFollow ?? opts.pull ?? d.pull,
      color: opts.color ?? d.color,
    };
    this.svg = this.buildSvg();
    this.arms = this.buildArms();
    this.onScrollOrResize = (): void => {
      this.rectCache.clear();
    };
  }

  mount(scope: HTMLElement | null, linkSelector: string): void {
    if (this._mounted) return;
    this._mounted = true;
    window.addEventListener("scroll", this.onScrollOrResize, { passive: true });
    window.addEventListener("resize", this.onScrollOrResize);
    const parent = scope ?? document.body;
    parent.appendChild(this.svg);
    this.rafLoop();
    const elements = scope
      ? scope.querySelectorAll<HTMLElement>(linkSelector)
      : document.querySelectorAll<HTMLElement>(linkSelector);
    this.bind(elements);
  }


  static createForDrawer(
    drawer: HTMLElement,
    gsapInstance: MagneticCornerGsap,
  ): MagneticCornerTracker | null {
    if (!MAGNETIC_CORNER_ENABLED) return null;
    const tracker = new MagneticCornerTracker({}, gsapInstance);
    tracker.mount(drawer, MAGNETIC_CORNER_DRAWER_LINK_SELECTOR);
    return tracker;
  }


  static init(options: MagneticCornerTrackerOptions = {}): MagneticCornerTracker | null {
    const gsap = getGsapGlobal();
    if (!MAGNETIC_CORNER_ENABLED) return null;
    if (!gsap || MAGNETIC_CORNER_ENTRIES.length === 0) return null;
    const root = options.root ?? document;



    MagneticCornerTracker.destroyAll();

    let first: MagneticCornerTracker | null = null;
    for (const entry of MAGNETIC_CORNER_ENTRIES) {
      const list = root.querySelectorAll<HTMLElement>(entry.selector);
      if (list.length === 0) continue;
      const tracker = new MagneticCornerTracker(
        {
          ...(entry.options as MagneticCornerTrackerOptions),
          root,
        },
        gsap,
      );
      tracker.mount(root instanceof HTMLElement ? root : null, entry.selector);
      MagneticCornerTracker._globalInstances.push(tracker);
      if (!first) first = tracker;
    }
    return first;
  }


  static destroyAll(): void {
    for (const t of MagneticCornerTracker._globalInstances) {
      t.destroy();
    }
    MagneticCornerTracker._globalInstances.length = 0;
  }

  private gsapTo(target: unknown, vars: object): { kill?: () => void } {
    return this.gsap.to(target, vars) as { kill?: () => void };
  }

  private buildSvg(): SVGSVGElement {
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    Object.assign(svg.style, {
      position: "fixed",
      inset: "0",
      width: "100%",
      height: "100%",
      pointerEvents: "none",
      zIndex: "101",
      overflow: "visible",
    });
    return svg;
  }

  private buildArms(): Record<string, SVGPathElement> {
    const out: Record<string, SVGPathElement> = {};
    const ns = "http://www.w3.org/2000/svg";
    MAGNETIC_CORNER_ARM_IDS.forEach((id) => {
      const p = document.createElementNS(ns, "path");
      p.setAttribute("fill", "none");
      p.setAttribute("stroke", this.cfg.color);
      p.setAttribute("stroke-linecap", "square");
      p.setAttribute("stroke-width", MAGNETIC_CORNER_STROKE_WIDTH);
      p.style.filter = `drop-shadow(0 0 5px ${this.cfg.color}88)`;
      this.svg.appendChild(p);
      out[id] = p;
    });
    return out;
  }

  private rafLoop = (): void => {
    if (this.dirty) {
      this.flush();
      this.dirty = false;
    }
    this.rafId = FrameScheduler.request(this.rafLoop);
  };

  private flush(): void {
    const { x0, y0, x1, y1, L, p } = this.H;
    const visible = p > 0.001;

    MAGNETIC_CORNER_ARM_IDS.forEach((id, i) => {
      const el = this.arms[id];
      if (!visible) {
        el.setAttribute("visibility", "hidden");
        this.cache[id + "d"] = "";
        this.cache[id + "da"] = "";
        this.cache[id + "do"] = "";
        return;
      }

      el.removeAttribute("visibility");
      const off = +(L * (1 - p)).toFixed(3);
      const len = +L.toFixed(3);
      const defs: [number, number, number, number][] = [
        [x0, y0, x0 + L, y0],
        [x0, y0, x0, y0 + L],
        [x1, y0, x1 - L, y0],
        [x1, y0, x1, y0 + L],
        [x0, y1, x0 + L, y1],
        [x0, y1, x0, y1 - L],
        [x1, y1, x1 - L, y1],
        [x1, y1, x1, y1 - L],
      ];
      const [ax, ay, bx, by] = defs[i] as [number, number, number, number];
      const d = `M ${+ax.toFixed(2)},${+ay.toFixed(2)} L ${+bx.toFixed(2)},${+by.toFixed(2)}`;
      const lenStr = String(len);
      const offStr = String(off);
      if (this.cache[id + "d"] !== d) {
        el.setAttribute("d", d);
        this.cache[id + "d"] = d;
      }
      if (this.cache[id + "da"] !== lenStr) {
        el.setAttribute("stroke-dasharray", lenStr);
        this.cache[id + "da"] = lenStr;
      }
      if (this.cache[id + "do"] !== offStr) {
        el.setAttribute("stroke-dashoffset", offStr);
        this.cache[id + "do"] = offStr;
      }
    });
  }

  private measureBox(el: HTMLElement): MagneticCornerBox {
    const cached = this.rectCache.get(el);
    if (cached) return cached;
    const g = this.cfg.gap;
    const r = el.getBoundingClientRect();
    const s = Math.min(r.width, r.height);
    const box: MagneticCornerBox = {
      cx: r.left + r.width / 2,
      cy: r.top + r.height / 2,
      hw: r.width / 2,
      hh: r.height / 2,
      x0: r.left - g,
      y0: r.top - g,
      x1: r.right + g,
      y1: r.bottom + g,
      L:
        s >= MAGNETIC_CORNER_SIZE_THRESHOLD
          ? MAGNETIC_CORNER_ARM_FIXED
          : Math.max(MAGNETIC_CORNER_ARM_MIN, s * MAGNETIC_CORNER_ARM_RATIO_SMALL),
      sw: Math.max(1.5, s * 0.022),
    };
    this.rectCache.set(el, box);
    return box;
  }

  private hoverIn(box: MagneticCornerBox): void {
    this.hoverTween?.kill?.();
    this.progressTween?.kill?.();
    Object.values(this.arms).forEach((a) =>
      a.setAttribute("stroke-width", MAGNETIC_CORNER_STROKE_WIDTH),
    );
    this.hoverTween = this.gsapTo(this.H, {
      x0: box.x0,
      y0: box.y0,
      x1: box.x1,
      y1: box.y1,
      L: box.L,
      duration: 0.42,
      ease: "power3.out",
      onUpdate: () => (this.dirty = true),
      overwrite: "auto",
    });
    this.progressTween = this.gsapTo(this.H, {
      p: 1,
      duration: 0.32,
      ease: "power3.out",
      onUpdate: () => (this.dirty = true),
    });
  }

  private hoverOut(): void {
    this.hoverTween?.kill?.();
    this.hoverTween = null;
    this.progressTween?.kill?.();
    this.progressTween = this.gsapTo(this.H, {
      p: 0,
      duration: 0.25,
      ease: "power2.in",
      onUpdate: () => (this.dirty = true),
      onComplete: () => {
        this.hoverTween?.kill?.();
        this.hoverTween = null;
        this.dirty = true;
      },
    });
  }

  private isActiveEl(el: HTMLElement): boolean {
    return MAGNETIC_CORNER_ACTIVE_EXCLUDE.some((s) => el.closest(s) !== null);
  }

  private bind(elements: NodeListOf<Element>): void {
    const { pull, pullText, cornerFollow } = this.cfg;
    const g = this.gsap;

    elements.forEach((el) => {
      const target = el as HTMLElement;
      const txt = target.querySelector<HTMLElement>(MAGNETIC_CORNER_TEXT_SELECTOR) ?? null;

      target.addEventListener("mouseenter", () => {
        if (this.isActiveEl(target)) return;
        this.hoverEl = target;
        const box = this.measureBox(target);
        this.hoverIn(box);
      });

      target.addEventListener("mouseleave", () => {
        this.hoverEl = null;
        FrameScheduler.request(() => {
          if (!this.hoverEl) this.hoverOut();
        });
        g.to(target, { x: 0, y: 0, duration: 0.5, ease: "elastic.out(1,.5)" });
        if (txt)
          g.to(txt, { x: 0, y: 0, duration: 0.4, ease: "elastic.out(1,.5)" });
      });

      target.addEventListener("mousemove", (e: MouseEvent) => {
        this.pendingMove = { el: target, txt, x: e.clientX, y: e.clientY };
        if (this.moveScheduled) return;
        this.moveScheduled = true;
        FrameScheduler.request(() => {
          this.moveScheduled = false;
          const p = this.pendingMove;
          if (!p || this.hoverEl !== p.el) return;
          if (this.isActiveEl(p.el)) {
            this.hoverEl = null;
            this.hoverOut();
            return;
          }
          const b = this.rectCache.get(p.el);
          if (!b) return;
          const rx = (p.x - b.cx) / b.hw;
          const ry = (p.y - b.cy) / b.hh;
          const bx = rx * b.hw * pull;
          const by = ry * b.hh * pull;

          const cornerOffset = pull !== 0 ? cornerFollow : 0;
          const bxCorner = rx * b.hw * cornerOffset;
          const byCorner = ry * b.hh * cornerOffset;
          g.to(p.el, {
            x: bx,
            y: by,
            duration: 0.35,
            ease: "power2.out",
            overwrite: "auto",
          });
          if (p.txt && pull !== 0)
            g.to(p.txt, {
              x: bx * (pullText / pull),
              y: by * (pullText / pull),
              duration: 0.25,
              ease: "power2.out",
              overwrite: "auto",
            });
          this.hoverTween?.kill?.();
          this.hoverTween = this.gsapTo(this.H, {
            x0: b.x0 + bxCorner,
            y0: b.y0 + byCorner,
            x1: b.x1 + bxCorner,
            y1: b.y1 + byCorner,
            duration: 0.35,
            ease: "power2.out",
            onUpdate: () => (this.dirty = true),
            overwrite: "auto",
          });
        });
      });
    });
  }

  destroy(): void {
    window.removeEventListener("scroll", this.onScrollOrResize);
    window.removeEventListener("resize", this.onScrollOrResize);
    this._mounted = false;
    this.rectCache.clear();
    FrameScheduler.cancel(this.rafId);
    this.gsap.killTweensOf([this.H]);
    this.hoverTween?.kill?.();
    this.progressTween?.kill?.();

    this.H.p = 0;
    this.dirty = true;
    this.flush();
    this.svg.remove();
  }
}



let staticCornerResizeBound = false;

function handleStaticCornerResize(): void {
  updateStaticCornerSizes();
}





export function updateStaticCornerSizes(root?: ParentNode | null): void {
  if (typeof document === "undefined") return;
  const scope = root ?? document;
  const brackets = scope.querySelectorAll<HTMLElement>(".no-corner-bracket");
  if (brackets.length === 0) return;
  brackets.forEach((el) => {
    const parent = el.parentElement;
    if (!parent) return;
    const r = parent.getBoundingClientRect();
    const s = Math.min(r.width, r.height);
    const size =
      s >= CORNER_SIZE_THRESHOLD
        ? CORNER_BRACKET_SIZE_FIXED
        : CORNER_BRACKET_SIZE_MIN;
    el.style.setProperty("--corner-bracket-size", `${size}px`);
  });

  if (!staticCornerResizeBound) {
    staticCornerResizeBound = true;
    window.addEventListener("resize", handleStaticCornerResize, { passive: true });
  }
}

