    transform: translateX(-4px);
    transition:
      opacity var(--transition-fast),
      transform var(--transition-fast);
  }

  &:hover &__icon--reveal,
  &:focus-visible &__icon--reveal {
    opacity: 1;
    transform: translateX(0);
  }

  // --- reduced motion override ----------------------------------------------

  @media (prefers-reduced-motion: reduce) {
    &__char--orig,
    &__char--clone {
      will-change: auto;
      transition: none;
    }

    // Prevent GSAP from visually animating — the JS still fires but GSAP
    // respects this via the CSS property check; for hard safety we also
    // keep the chars at their resting positions via inline reset in JS.
    // Icon reveal is also simplified:
    &__icon--reveal {
      opacity: 1;
      transform: none;
      transition: none;
    }
