# Plan: `no-btn-char` — Per-Character Rolling Text Button

## Context

버튼 호버 시 각 글자가 위로 말리며 교체되는 GSAP 텍스트 롤링 효과. 현재 HTML 구조는 이미 일부 뷰에서 사용 중이므로, 기존 구조를 그대로 animate하거나 JS가 DOM을 자동 빌드하는 방식 모두 지원해야 함.

## Design Decisions

- **DOM 빌드**: `data-char-btn` 속성 없이 `.no-btn-char` 안의 `.no-btn-char__text`를 감지. 이미 `__cell`이 있으면 skip (idempotent). 없으면 텍스트를 글자 단위로 분해해 `__cell > __char--orig + __char--clone` 구조를 자동 생성.
- **아이콘 reveal**: CSS `transition`만 사용 (GSAP 불필요).
- **Stagger**: enter/leave 모두 left-to-right, 0.03s.

## Files to Change

| # | Action | File |
|---|--------|------|
| 1 | CREATE | `resource/ts/components/CharBtn.ts` |
| 2 | MODIFY | `resource/ts/types/component.types.ts` |
| 3 | MODIFY | `resource/ts/config/component.config.ts` |
| 4 | MODIFY | `resource/ts/runtime/PageRuntime.ts` |
| 5 | MODIFY | `resource/scss/components/_button.scss` |

---

## Step 1 — CREATE `resource/ts/components/CharBtn.ts`

```typescript
import { CHAR_BTN } from "../config/component.config.js";
import type { CharBtnInitOptions } from "../types/component.types.js";
import type { GsapGlobal, WindowWithGsap } from "../types/gsap.types.js";

function getGsap(): GsapGlobal | null {
  return (window as WindowWithGsap).gsap ?? null;
}

function buildCells(textEl: HTMLElement): void {
  if (textEl.querySelector(`.${CHAR_BTN.cellClass}`)) return;
  const raw = textEl.textContent ?? "";
  textEl.textContent = "";
  for (const char of raw) {
    const cell = document.createElement("span");
    cell.className = CHAR_BTN.cellClass;
    const orig = document.createElement("span");
    orig.className = `${CHAR_BTN.charClass} ${CHAR_BTN.origClass}`;
    orig.textContent = char;
    const clone = document.createElement("span");
    clone.className = `${CHAR_BTN.charClass} ${CHAR_BTN.cloneClass}`;
    clone.textContent = char;
    cell.appendChild(orig);
    cell.appendChild(clone);
    textEl.appendChild(cell);
  }
}

class CharBtnInstance {
  private readonly _root: HTMLElement;
  private _origChars: HTMLElement[] = [];
  private _cloneChars: HTMLElement[] = [];
  private readonly _onEnter: () => void;
  private readonly _onLeave: () => void;

  constructor(root: HTMLElement) {
    this._root = root;
    this._onEnter = this._handleEnter.bind(this);
    this._onLeave = this._handleLeave.bind(this);
  }

  mount(): void {
    const textEl = this._root.querySelector<HTMLElement>(`.${CHAR_BTN.textClass}`);
    if (!textEl) return;
    buildCells(textEl);
    this._origChars = Array.from(textEl.querySelectorAll<HTMLElement>(`.${CHAR_BTN.origClass}`));
    this._cloneChars = Array.from(textEl.querySelectorAll<HTMLElement>(`.${CHAR_BTN.cloneClass}`));
    if (this._origChars.length === 0) return;
    this._root.dataset[CHAR_BTN.boundAttr] = "true";
    this._root.addEventListener("mouseenter", this._onEnter);
    this._root.addEventListener("mouseleave", this._onLeave);
  }

  destroy(): void {
    this._root.removeEventListener("mouseenter", this._onEnter);
    this._root.removeEventListener("mouseleave", this._onLeave);
    const gsap = getGsap();
    if (gsap) {
      gsap.killTweensOf?.(this._origChars);
      gsap.killTweensOf?.(this._cloneChars);
      gsap.set(this._origChars, { yPercent: 0 });
      gsap.set(this._cloneChars, { yPercent: 100 });
    }
    delete this._root.dataset[CHAR_BTN.boundAttr];
  }

  private _handleEnter(): void {
    const gsap = getGsap();
    if (!gsap) return;
    gsap.killTweensOf?.(this._origChars);
    gsap.killTweensOf?.(this._cloneChars);
    gsap.to(this._origChars, { yPercent: -100, duration: CHAR_BTN.duration, ease: CHAR_BTN.ease, stagger: CHAR_BTN.stagger, overwrite: "auto" });
    gsap.to(this._cloneChars, { yPercent: 0,    duration: CHAR_BTN.duration, ease: CHAR_BTN.ease, stagger: CHAR_BTN.stagger, overwrite: "auto" });
  }

  private _handleLeave(): void {
    const gsap = getGsap();
    if (!gsap) return;
    gsap.killTweensOf?.(this._origChars);
    gsap.killTweensOf?.(this._cloneChars);
    gsap.to(this._origChars, { yPercent: 0,   duration: CHAR_BTN.duration, ease: CHAR_BTN.ease, stagger: CHAR_BTN.stagger, overwrite: "auto" });
    gsap.to(this._cloneChars, { yPercent: 100, duration: CHAR_BTN.duration, ease: CHAR_BTN.ease, stagger: CHAR_BTN.stagger, overwrite: "auto" });
  }
}

export class CharBtn {
  private static _instances: CharBtnInstance[] = [];

  static init(options: CharBtnInitOptions = {}): void {
    CharBtn.dispose();
    const selector = options.selector ?? CHAR_BTN.selector;
    const root = options.root ?? document;
    Array.from(root.querySelectorAll<HTMLElement>(selector))
      .filter((el) => !el.dataset[CHAR_BTN.boundAttr])
      .forEach((el) => {
        const inst = new CharBtnInstance(el);
        inst.mount();
        CharBtn._instances.push(inst);
      });
  }

  static dispose(): void {
    CharBtn._instances.forEach((inst) => inst.destroy());
    CharBtn._instances = [];
  }
}
```

