  private static _instances: CharBtnInstance[] = [];

  static init(options: CharBtnInitOptions = {}): void {
    CharBtn.dispose();
    const selector = options.selector ?? CHAR_BTN.selector;
    const root = options.root ?? document;
    Array.from(root.querySelectorAll<HTMLElement>(selector))
      .filter((el) => !el.dataset[CHAR_BTN.boundAttr])
      .forEach((el) => {
        const inst = new CharBtnInstance(el);
        inst.mount();
        CharBtn._instances.push(inst);
      });
  }

  static dispose(): void {
    CharBtn._instances.forEach((inst) => inst.destroy());
    CharBtn._instances = [];
  }
}
