import type { TimelineTweenPropsMap } from "./object.types.js";

export type TimelinePosition =
  | number
  | ">"
  | "<"
  | "="
  | `+=${number}`
  | `-=${number}`
  | `${">" | "<"}+=${number}`
  | `${">" | "<"}-=${number}`
  | `${string}`
  | `${string}+=${number}`
  | `${string}-=${number}`;


export interface TimelineControlMethods {
  add(callback: () => void, position?: TimelinePosition): this;
  addLabel(name: string, position?: TimelinePosition): this;
  pause(): this;
  resume(): this;
  play(): void;
  kill(): void;
  progress(value?: number): number | this;
  duration(): number;
  timeScale(value: number): this;
}



export interface GSAPTimeline extends TimelineControlMethods {
  add(callback: () => void, position?: TimelinePosition): this;
  add(timeline: GSAPTimeline, position?: TimelinePosition): this;
  to(target: unknown, vars: object, position?: TimelinePosition): this;
  from(target: unknown, vars: object, position?: TimelinePosition): this;
  fromTo(
    target: unknown,
    fromVars: object,
    toVars: object,
    position?: TimelinePosition,
  ): this;
  set(target: unknown, vars: object, position?: TimelinePosition): this;
  addPause(position?: TimelinePosition, callback?: () => void): this;
  paused(value?: boolean): boolean | this;
  eventCallback?(name: string, cb?: () => void): unknown;
  currentLabel?(value?: string): string;
  tweenTo?(
    label: string,
    vars?: { onComplete?: () => void; duration?: number; ease?: string },
  ): unknown;
}



export interface GsapTweenMeta {
  duration?: number;
  ease?: string;
  delay?: number;
}


export type DomTweenVars = GsapTweenMeta & {
  [key: string]: unknown;
};

export type RiseState = "up";
export type LegacyRiseStateFlagKey = "riseUp";
export type LegacyRiseStateFlags = Partial<
  Record<LegacyRiseStateFlagKey, boolean>
>;



type CameraScrollVars = Partial<
  Pick<
    TimelineTweenPropsMap["camera"],
    "position" | "scale" | "fov" | "near" | "far"
  >
>;


export type TextRevealVars = LegacyRiseStateFlags & {
  riseState?: RiseState;
  revealClass?: string;
};

export type ScrollSceneControlVars<K extends string> = ((K extends "camera"
  ? CameraScrollVars
  : K extends "mainBackground" | "aboutBackground"
    ? Partial<TimelineTweenPropsMap[K]>
    : K extends keyof TimelineTweenPropsMap
      ? Partial<TimelineTweenPropsMap[K]>
      : DomTweenVars) &
  GsapTweenMeta) &
  {
    scrollWeight?: number;
    scroll?: number;
  } &
  Partial<TextRevealVars>;


export interface StrictTimelineScroll extends TimelineControlMethods {
  to<K extends string>(
    target: K,
    vars: ScrollSceneControlVars<K>,
    position?: TimelinePosition,
  ): StrictTimelineScroll;
  from<K extends string>(
    target: K,
    vars: ScrollSceneControlVars<K>,
    position?: TimelinePosition,
  ): StrictTimelineScroll;

  fromTo<K extends string>(
    target: K,
    fromVars: DomTweenVars,
    toVars: DomTweenVars,
    position?: TimelinePosition,
  ): StrictTimelineScroll;
  seek(position: TimelinePosition): StrictTimelineScroll;
}


export interface GsapTweenLike {
  kill?: () => void;
}


export interface GsapGlobal {
  timeline: (vars?: object) => GSAPTimeline;
  registerPlugin: (...plugins: unknown[]) => void;
  set: (target: unknown, vars: object) => void;
  to: (target: unknown, vars: object) => unknown;
  killTweensOf?: (target: unknown) => void;
  fromTo: (
    target: unknown,
    fromVars: object,
    toVars: object,
    vars?: object,
  ) => unknown;
  delayedCall?: (delay: number, callback: () => void) => GsapTweenLike;
}


export interface ScrollTriggerGlobal {
  create: (options: {
    trigger?: Element | string;
    start?: string;
    end?: string | (() => string);
    scrub?: boolean | number;
    pin?: Element | string | false;
    pinSpacing?: boolean;
    anticipatePin?: number;
    pinType?: "fixed" | "transform";
    pinReparent?: boolean;
    animation?: GSAPTimeline;
    invalidateOnRefresh?: boolean;
    immediateRender?: boolean;
    onUpdate?: (self: { progress?: number }) => void;
  }) => { kill: () => void };
  update: () => void;
  refresh?: () => void;
}


export interface WindowWithGsap extends Window {
  gsap?: GsapGlobal;
  ScrollTrigger?: ScrollTriggerGlobal;
}

