// no-btn-char — per-character rolling text button
.no-btn-char {
  display: inline-flex;
  align-items: center;
  gap: fluid(6, 10);
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  color: inherit;

  &--sm { @include font("f-body-3"); }
  &--md { @include font("f-body-2"); }
  &--lg { @include font("f-body-1"); }

  &__text {
    display: inline-flex;
    align-items: center;
  }

  &__cell {
    position: relative;
    overflow: hidden;
    display: inline-block;
  }

  &__char {
    display: inline-block;
    will-change: transform;

    &--clone {
      position: absolute;
      top: 0;
      left: 0;
      transform: translateY(100%);
    }
  }

  &__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: fluid(12, 14);
  }

  &__icon--reveal {
    opacity: 0;
    transform: translateX(-4px);
    transition:
      opacity var(--transition-fast),
      transform var(--transition-fast);
  }

  &:hover &__icon--reveal,
  &:focus-visible &__icon--reveal {
    opacity: 1;
    transform: translateX(0);
  }

  @media (prefers-reduced-motion: reduce) {
    &__char { will-change: auto; }

    &__icon--reveal {
      opacity: 1;
      transform: none;
      transition: none;
    }
  }
}

